/* ATB Atlas V17 — Spectrum OS: vivid medical editorial, source-grounded relationships.
   Educational content does not replace clinical susceptibility or guidelines. */
'use strict';
const $=s=>document.querySelector(s);
const H=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const storage={get(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
const ICONS={map:'table-2',micro:'microscope',drugs:'pill',clinic:'stethoscope',compare:'columns-3',learn:'graduation-cap',lab:'flask-conical',sources:'book-open',search:'search',palette:'palette',filter:'sliders-horizontal',reset:'rotate-ccw',next:'arrow-right',external:'external-link',note:'lightbulb',star:'shield-check',info:'info',help:'circle-help',more:'chevron-down',chevron:'chevron-right',grid:'grid-3x3',layers:'layers',swap:'arrow-left-right',alert:'shield-alert',close:'x',dna:'dna',menu:'list-filter',book:'book-open'};
const ic=(name,size=18)=>`<img class="ico" width="${size}" height="${size}" alt="" src="assets/icons/${ICONS[name]||name}.svg">`;
const NAV=[['mapa','map','Mapa'],['micro','micro','Microorganismos'],['atb','drugs','Antibióticos'],['clinica','clinic','Síndromes'],['comparar','compare','Comparador'],['aprender','learn','Aprender'],['laboratorio','lab','Laboratorio'],['fuentes','sources','Fuentes']];
const GROUP_PALETTE=['#6b2fc4','#2f6f9f','#b23a55','#2b7d6a','#a0558e','#46508e','#0a86b8','#7a46c8','#c2456f','#5b7a2a','#8a4aa8','#3b4fa6'];
const PRESETS={
  'Resonancia':['#E33E70','#609dc9','#8654D5','#3977a4','#2D86D6','#00A48C','#6977DA','#4c91c3','#1EA585','#C65FA8','#4884ae','#5469C8'],
  'Tropical Lab':['#EE5B77','#5597c6','#AE53D0','#3EAC63','#247AC1','#00A6B0','#7663D6','#5798c6','#4e7ea1','#CD568A','#6796cc','#6681CC'],
  'Nocturno':['#FF5E97','#7ba4d3','#AA80F8','#5999c7','#5CB1FA','#30CEB5','#91A0FF','#79a3d2','#47D0A0','#F092D3','#8eb1d9','#8FA1FF'],
  'Museo Médico':['#C8426C','#4e92c3','#7852A8','#436a86','#3C75AC','#158B7D','#6779B5','#3d81b2','#418C72','#A35891','#4b7da0','#4F639D']
};
const ST={active:{name:'Actividad habitual',short:'Actividad',mark:'✓',help:'Relación registrada como actividad habitual; necesita interpretación clínica y susceptibilidad.'},conditional:{name:'Según contexto',short:'Variable',mark:'≈',help:'Relación condicionada por fenotipo, susceptibilidad, sitio o circunstancia clínica.'},none:{name:'Sin actividad útil',short:'No útil',mark:'×',help:'Relación registrada como actividad no útil para este microorganismo.'},unknown:{name:'Sin evaluar',short:'Sin datos',mark:'·',help:'No existe una relación registrada. NO equivale a resistencia ni inactividad.'}};
const state={route:'mapa',group:'all',family:'all',search:'',onlyKnown:true,scope:'groups',page:0,perPage:10,sort:'evidence',favoritesOnly:false,drug:'',micro:'',syndrome:'',microGroup:'all',drugFamily:'all',browserQuery:'',profileTab:'identidad',drugTab:'resumen',clinicalTab:'panorama',compare:[],compareMicro:'',lesson:'f01',lessonAnswered:false,labSyndrome:'',labMicro:'',labDrug:'',labStep:0,modal:'',palette:storage.get('atlas_v17_palette',null),favorites:storage.get('atlas_v16_favorites',[]),completed:storage.get('atlas_v16_completed',[]),savedViews:storage.get('atlas_v16_views',[]),compact:false,showFilters:false};
let D=null,F=null,X=null, byDrug=new Map(),byPath=new Map(), byPair=new Map();
const entity=(kind,id)=>D[kind].find(x=>x.id===id);
const A=id=>entity('antibiotics',id),P=id=>entity('pathogens',id),G=id=>entity('groups',id),S=id=>entity('syndromes',id);
const members=gid=>D.pathogens.filter(p=>p.groupId===gid);
const relation=(a,p)=>byPair.get(`${a}|${p}`);
const relsA=id=>byDrug.get(id)||[];const relsP=id=>byPath.get(id)||[];
const rstatus=(r)=>r?['active','conditional','none'].includes(r.status)?r.status:'unknown':'unknown';
const grpcolor=id=>{const n=D.groups.findIndex(g=>g.id===id);return (GROUP_PALETTE[n] || '#5b7fd6');};
const pill=(s)=>`<span class="pill">${H(s)}</span>`;
const tag=(s)=>`<span class="kicker">${H(s)}</span>`;
const button=(label,act,style='quiet',ico='')=>`<button class="btn ${style}" data-act="${H(act)}">${ico?ic(ico,16):''}${H(label)}</button>`;
const countText=(x)=>Number(x).toLocaleString('es-MX');
function linkRefs(keys=[]){return [...new Set(keys||[])].filter(k=>D.guides[k]).map(k=>`<a class="source-pill" href="${H(D.guides[k].url||'#') }" ${D.guides[k].url?'target="_blank" rel="noopener noreferrer"':''}>${H(D.guides[k].title)} ${D.guides[k].url?ic('external',12):''}</a>`).join('')||'<small class="muted">Sin referencias adicionales asignadas a esta ficha.</small>';}
function spectrumStats(a,g){const vals=members(g.id).map(p=>rstatus(relation(a.id,p.id)));const count=vals.filter(x=>x!=='unknown').length;return {vals,total:vals.length,known:count,active:vals.filter(x=>x==='active').length,conditional:vals.filter(x=>x==='conditional').length,none:vals.filter(x=>x==='none').length};}
function statusBadge(v){return `<span class="status-badge s-${v}"><b>${ST[v].mark}</b>${ST[v].short}</span>`}
function escapeHandler(){window.addEventListener('hashchange',()=>{const x=(location.hash.replace(/^#\//,'').split('?')[0]||'mapa');if(NAV.some(y=>y[0]===x)){state.route=x;state.modal='';render()}})}
function goto(route){state.route=route;state.modal='';if(location.hash!==`#/${route}`)history.replaceState(null,'',location.pathname+location.search+'#/'+route);render();window.scrollTo({top:0,behavior:'instant'})}
function persist(){storage.set('atlas_v17_palette',state.palette);storage.set('atlas_v16_favorites',state.favorites);storage.set('atlas_v16_completed',state.completed);storage.set('atlas_v16_views',state.savedViews)}
function applyColors(){const palette=GROUP_PALETTE;D.groups.forEach((g,i)=>document.documentElement.style.setProperty(`--group-${g.id}`,palette[i]||GROUP_PALETTE[i]||'#71819a'));}
function groupStyle(gid){return `style="--tone:${grpcolor(gid)}"`}
function legacy_header(){return `<div class="header-wrap"><header class="masthead"><button class="brand" data-act="nav:mapa"><span class="brand-icon">${ic('dna',24)}</span><span><strong>ATB<span> / </span>ATLAS</strong><small>MICROBIOLOGÍA VISUAL · ESPECTRO · CLÍNICA</small></span></button><div class="mast-actions"><button data-act="search-global" class="search-launch">${ic('search',16)} <span>Buscar fármaco, micro o síndrome…</span><kbd>⌘ K</kbd></button>${button('Colores','palette','secondary','palette')}<button class="mobile-nav" data-act="menu">${ic('menu',20)}</button></div></header><nav id="site-nav" class="site-nav">${NAV.map(([id,ico,label],i)=>`<button class="site-tab ${state.route===id?'on':''}" data-act="nav:${id}">${ic(ico,16)}${H(label)}<span>${('0'+(i+1)).slice(-2)}</span></button>`).join('')}</nav></div>`}
function legacy_footer(){return `<footer class="app-footer"><span>ATB / ATLAS · EDICIÓN 17</span><p>Material para estudio médico. La cobertura microbiológica, los capítulos educativos y la decisión clínica son capas diferentes. No usar para prescribir sin susceptibilidad, contexto y guía vigente.</p><a href="https://github.com/ProQuincy2471/atb-atlas" target="_blank" rel="noopener noreferrer">Repositorio ${ic('external',13)}</a></footer>`}
function frame(content){return `<div class="layout">${header()}<main id="main" class="main">${content}</main>${footer()}</div>${modal()}`}
function pageHead(idx,over,title,desc,acts=''){return `<div class="page-head page-head-v17"><div><div class="page-eyebrow"><span class="page-index">${H(idx)}</span>${tag(over)}<span class="page-version">EDICIÓN VISUAL 17</span></div><h1>${title}</h1><p>${desc}</p></div>${acts?`<div class="head-actions">${acts}</div>`:''}</div>`}
function drugSpectrumDossier(a){const groups=D.groups;return `<section class="dossier-section"><div class="dossier-header"><div><span class="kicker">CARTOGRAFÍA DE LA FICHA</span><h4>Doce territorios, una lectura.</h4><p>El número indica relaciones registradas, <strong>no</strong> porcentaje de eficacia. Abre un territorio para examinar sus especies.</p></div><span class="dossier-count">${relsA(a.id).length} / ${D.pathogens.length} cruces</span></div><div class="dossier-territories">${groups.map(g=>{const st=spectrumStats(a,g);return `<button ${groupStyle(g.id)} data-act="drug-territory:${a.id}:${g.id}" class="dossier-territory"><i></i><span>${H(g.name)}</span><strong>${st.known}<small> / ${st.total}</small></strong><em>${st.active} act. · ${st.conditional} var.</em></button>`}).join('')}</div></section>`}
function microRelationsDossier(p){const vals=relsP(p.id),arr=[...vals].sort((a,b)=>({active:0,conditional:1,none:2}[rstatus(a)]??3)-({active:0,conditional:1,none:2}[rstatus(b)]??3));return `<section class="dossier-section micro-dossier" ${groupStyle(p.groupId)}><div class="dossier-header"><div><span class="kicker">CONEXIONES DOCUMENTADAS</span><h4>Del microorganismo al espectro.</h4><p>Explora las relaciones explícitas del catálogo. Los pares ausentes no son sinónimo de resistencia.</p></div><span class="dossier-count">${vals.length} pares cargados</span></div><div class="micro-relation-track">${arr.slice(0,9).map(r=>`<button data-act="open-drug:${r.antibiotic}"><span class="micro-status-mark st-${rstatus(r)}">${ST[rstatus(r)].mark}</span><strong>${H(A(r.antibiotic)?.name||r.antibiotic)}</strong><small>${H(ST[rstatus(r)].short)}</small></button>`).join('')||'<p class="muted">Esta especie todavía no tiene cruces individuales registrados.</p>'}</div></section>`}
function groupRail(){const chosen=state.group;return `<div class="group-rail" role="group" aria-label="Grupos microbiológicos"><button class="group-tab ${chosen==='all'?'on':''}" data-act="group:all"><b>TODOS</b><small>12 territorios</small></button>${D.groups.map(g=>`<button ${groupStyle(g.id)} class="group-tab ${chosen===g.id?'on':''}" data-act="group:${g.id}"><span class="color-rail"></span><b>${H(g.name)}</b><small>${members(g.id).length} organismos</small></button>`).join('')}</div>`}
function mapDrugs(){let arr=D.antibiotics.filter(a=>(state.family==='all'||a.family===state.family)&&(!state.search||[a.name,a.family,a.subgroup].join(' ').toLowerCase().includes(state.search.toLowerCase())));
 if(state.onlyKnown) arr=arr.filter(a=>relsA(a.id).length);
 if(state.favoritesOnly)arr=arr.filter(a=>state.favorites.includes(a.id));if(state.sort==='family')arr.sort((a,b)=>a.family.localeCompare(b.family,'es')||a.name.localeCompare(b.name,'es'));else if(state.sort==='alpha')arr.sort((a,b)=>a.name.localeCompare(b.name,'es'));else arr.sort((a,b)=>relsA(b.id).length-relsA(a.id).length||a.name.localeCompare(b.name,'es'));
 return arr;
}
function mapControls(){const fam=[...new Set(D.antibiotics.map(a=>a.family))].sort((a,b)=>a.localeCompare(b,'es'));return `<div class="map-controls"><div class="search-control">${ic('search',16)}<input aria-label="Buscar antibiótico" id="map-search" value="${H(state.search)}" placeholder="Buscar ceftriaxona, carbapenémico…"></div><div class="map-controls-right"><div class="view-switch"><button class="${state.scope==='groups'?'on':''}" data-act="scope:groups">${ic('map',15)} Grupos</button><button class="${state.scope==='species'?'on':''}" data-act="scope:species">${ic('grid',15)} Especies</button></div><button class="btn secondary" data-act="toggle-filters">${ic('filter',16)} Filtros</button><button class="btn ghost" data-act="save-view">${ic('star',15)} Guardar</button><button class="btn ghost" data-act="show-views">${ic('layers',15)} Mis mapas</button><button class="btn ghost" data-act="reset-map">${ic('reset',15)} Limpiar</button></div></div>${state.showFilters?`<div class="advanced-filters"><label>Familia farmacológica<select id="map-family"><option value="all">Todas las familias</option>${fam.map(f=>`<option value="${H(f)}" ${state.family===f?'selected':''}>${H(f)}</option>`).join('')}</select></label><label class="switch-label"><input type="checkbox" id="map-known" ${state.onlyKnown?'checked':''}>Priorizar fármacos con relaciones registradas</label><label>Ordenar por<select id="map-sort"><option value="evidence" ${state.sort==='evidence'?'selected':''}>Más relaciones</option><option value="family" ${state.sort==='family'?'selected':''}>Por familia</option><option value="alpha" ${state.sort==='alpha'?'selected':''}>A–Z</option></select></label><label class="switch-label"><input type="checkbox" id="map-fav" ${state.favoritesOnly?'checked':''}>Solo favoritos</label><div><b>Visualización</b><p>Grupo resume los cruces por territorio; «Especies» muestra cada microorganismo individualmente. Los campos sin datos se mantienen rayados.</p></div></div>`:''}`}
function lane(a,g){const s=spectrumStats(a,g);const vals=s.vals;if(state.scope==='species')return `<div class="micro-cells">${members(g.id).map((p,i)=>{const v=vals[i];return `<button class="micro-cell st-${v}" data-act="relation:${a.id}:${p.id}" title="${H(p.name)} · ${H(ST[v].name)}">${ST[v].mark}</button>`}).join('')}</div>`;return `<button class="spectrum-lane" ${groupStyle(g.id)} data-act="inspect:${a.id}:${g.id}" aria-label="${H(a.name)} frente a ${H(g.name)}: ${s.known} de ${s.total} relaciones documentadas"><span class="lane-top"><i></i><small>${s.known}/${s.total}</small></span><span class="lane-bars">${vals.map(v=>`<i class="bar-seg st-${v}" title="${H(ST[v].name)}"></i>`).join('')}</span><span class="lane-bottom">${s.known?`${s.active} activas · ${s.conditional} variables`:'Sin registrar'}</span></button>`}
function tableMap(){const list=mapDrugs(),total=Math.max(1,Math.ceil(list.length/state.perPage));state.page=Math.min(state.page,total-1);const visible=list.slice(state.page*state.perPage,(state.page+1)*state.perPage);const groups=state.group==='all'?D.groups:D.groups.filter(g=>g.id===state.group);let family='',rows='';for(const a of visible){if(a.family!==family){family=a.family;rows+=`<tr class="family-line"><td colspan="${groups.length+1}"><span class="family-stripe"></span>${H(family)} <small>${list.filter(x=>x.family===family).length} agentes coincidentes</small></td></tr>`;}rows+=`<tr class="antibiotic-row"><th><button data-act="open-drug:${a.id}" class="drug-name"><strong>${H(a.name)}</strong><small>${H(a.subgroup)}</small></button></th>${groups.map(g=>`<td>${lane(a,g)}</td>`).join('')}</tr>`;}
 return `<div class="map-scroll"><table class="spectrum-table"><thead><tr><th class="corner-head">FÁRMACO <span>↓</span><small>MICROORGANISMO →</small></th>${groups.map(g=>`<th ${groupStyle(g.id)} class="group-header"><span class="group-header-stripe"></span><b>${H(g.name)}</b><small>${members(g.id).length} especies/fenotipos</small></th>`).join('')}</tr></thead><tbody>${rows||`<tr><td class="empty-map" colspan="${groups.length+1}">No hay fármacos para estos filtros. Restablece los filtros para ver el atlas.</td></tr>`}</tbody></table></div><div class="pagination"><div><b>${list.length}</b> antibióticos coincidentes · ${D.relations.length} cruces registrados</div><div><button data-act="prev-page" ${state.page===0?'disabled':''}>${ic('chevron',16)} Anterior</button><span>${state.page+1} / ${total}</span><button data-act="next-page" ${state.page>=total-1?'disabled':''}>Siguiente ${ic('chevron',16)}</button></div></div>`;}
function mapDetail(){const a=A(state.drug),g=G(state.group==='all'?D.groups[0].id:state.group);return ''}
function inspector(){if(!state.inspect)return `<div class="inspector-guide"><div class="inspect-symbol">${ic('info',30)}</div><h3>Selecciona una celda: entiende el porqué.</h3><p>Una selección revela especies, estados y notas clínicas. Puedes saltar a las fichas sin perder contexto. Ninguna casilla sin datos se convertirá en «resistente».</p><div class="inspect-steps"><span>01 / Grupo</span><span>02 / Especie</span><span>03 / Evidencia</span></div></div>`;
 const {drug,group,pathogen}=state.inspect;const a=A(drug),g=G(group);if(!a||!g)return '';
 if(pathogen){const p=P(pathogen),r=relation(drug,pathogen),s=rstatus(r);return `<div class="inspector-detail" ${groupStyle(group)}><div class="inspect-overline">CRUCE POR ESPECIE</div><h3>${H(a.name)} <em>×</em> ${H(p.name)}</h3>${statusBadge(s)}<p>${H(r?.note||ST.unknown.help)}</p><div class="evidence-alert">${ic('alert',17)}${r?'Relación del piloto: pendiente de validación clínica individual.':'No hay relación cargada: no se puede inferir susceptibilidad ni resistencia.'}</div>${r?`<div class="info-pair"><span>Contexto</span><strong>${H(r.clinical||'Depende del foco clínico')}</strong></div><div class="references">${linkRefs(r.referenceKeys||r.sources)}</div>`:''}<div class="inspect-links">${button('Ficha del micro','open-micro:'+p.id,'secondary','micro')}${button('Ficha del ATB','open-drug:'+a.id,'secondary','drugs')}</div></div>`}
 return `<div class="inspector-detail" ${groupStyle(g.id)}><div class="inspect-overline">TERRITORIO SELECCIONADO</div><h3>${H(a.name)} <em>×</em> ${H(g.name)}</h3><p>El territorio contiene <b>${members(g.id).length}</b> especies o fenotipos. La actividad NO es uniforme dentro de un grupo. Selecciona una especie para ver su registro individual.</p><div class="species-result-list">${members(g.id).map(p=>{const r=relation(a.id,p.id),s=rstatus(r);return `<button data-act="species:${p.id}">${statusBadge(s)}<span>${H(p.name)}</span>${ic('chevron',13)}</button>`}).join('')}</div><div class="inspect-links">${button(state.favorites.includes(a.id)?'Quitar favorito':'Guardar favorito','favorites:'+a.id,'secondary','star')}${button('Ver antibiótico','open-drug:'+a.id,'secondary','drugs')}${button('Explorar grupo','filter-group:'+g.id,'secondary','micro')}</div></div>`;
}
function quickMicro(){const picked=['s-aureus-mrsa','p-aeruginosa','e-coli-blee','s-pneumoniae','b-fragilis','nocardia'];return `<div class="micro-quick"><span>ESPECIE RÁPIDA</span>${picked.filter(P).map(id=>`<button data-act="quick:${id}" ${groupStyle(P(id).groupId)}><i></i>${H(P(id).name)}</button>`).join('')}<button data-act="nav:micro">Todas las especies ${ic('next',13)}</button></div>`}
function spectrumRibbon(){return `<div class="spectrum-ribbon" aria-label="Doce colores para doce grupos microbiológicos"><div class="ribbon-badge"><span>ESPECTRO / IDENTIDAD</span><strong>Un color por territorio.</strong><small>La trama y el símbolo indican cobertura; el pigmento indica microbiología.</small></div><div class="ribbon-tones">${D.groups.map((g,i)=>`<button data-act="group:${g.id}" class="ribbon-tone" ${groupStyle(g.id)} aria-label="Ver ${H(g.name)}" title="${H(g.name)}"><span>${('0'+(i+1)).slice(-2)}</span></button>`).join('')}</div><button class="ribbon-help" data-act="legend">${ic('help',18)} Leer el mapa</button></div>`}
function legacy_mapPage(){const total=D.relations.length;return `<section class="map-section">${pageHead('01','SPECTRUM / STUDIO','Un mapa para <em>entender</em> el espectro.','Una cartografía editable: antibióticos en filas, territorios en columnas y actividad por especie. Visual primero, interpretación después.',button('Cómo interpretar','legend','secondary','help'))}${spectrumRibbon()}<div class="map-summary"><div><span class="round-index">01</span><b>Elige un grupo</b><small>Ubica el territorio microbiológico</small></div><div><span class="round-index">02</span><b>Selecciona una banda</b><small>Comprueba las especies del grupo</small></div><div><span class="round-index">03</span><b>Interpreta el cruce</b><small>Revisa fuente, estatus y contexto</small></div></div><div class="section-label">TERRITORIOS MICROBIOLÓGICOS <span>COLOR = IDENTIDAD, NO COBERTURA</span></div>${groupRail()}${quickMicro()}<div class="map-workspace"><div class="map-primary"><div class="folio-head"><div>${tag('FOLIO 01 / MAPA')}<h2>Cartografía antimicrobiana</h2><p>Mapa con datos explícitos y zonas sin evaluar diferenciadas mediante textura.</p></div><div class="map-figures"><span><b>${countText(D.antibiotics.length)}</b> ATB</span><span><b>${countText(D.pathogens.length)}</b> MICRO</span><span><b>${total}</b> CRUCES</span></div></div>${mapControls()}${tableMap()}<div class="map-legend"><div class="legend-heading"><b>Cómo leer cada segmento</b><small>El color de la cabecera identifica grupo · el símbolo define la relación</small></div>${Object.keys(ST).map(k=>`<button data-act="status:${k}">${statusBadge(k)}</button>`).join('')}${button('Ver leyenda','legend','ghost','help')}</div></div><aside class="map-inspector" id="inspector"><div class="inspector-head"><span>${ic('layers',16)} INTERPRETACIÓN</span>${state.inspect?`<button data-act="close-inspector">${ic('close',15)}</button>`:''}</div>${inspector()}</aside></div><div class="map-footer-note">${ic('alert',18)}<div><strong>Importante: cobertura ≠ prescripción.</strong> Los cruces del corpus son preliminares, no una base de antibiogramas validados. Una banda vacía significa «sin evaluar», no «resistente».</div></div></section>`}
function libraryHeader(label,title,desc){return pageHead(label,'BIBLIOTECA',title,desc)}
function catalog(kind){const micro=kind==='micro',all=micro?D.pathogens:D.antibiotics,groupKey=micro?'groupId':'family',field=micro?'group':'family';const current=micro?state.micro:state.drug;const filter=micro?state.microGroup:state.drugFamily;const terms=(state.browserQuery||'').toLowerCase();const values=micro?D.groups.map(x=>[x.id,x.name,members(x.id).length]):[...new Set(D.antibiotics.map(x=>x.family))].sort().map(x=>[x,x,D.antibiotics.filter(a=>a.family===x).length]);let filtered=all.filter(x=>(filter==='all'||x[groupKey]===filter)&&[x.name,x.aliases?.join(' '),x.subgroup,x.morphology,x.family].filter(Boolean).join(' ').toLowerCase().includes(terms));const chosen=all.find(x=>x.id===current)||filtered[0]||all[0];return `<div class="library-layout"><aside class="library-browser"><label class="search-control">${ic('search',16)}<input id="library-search" placeholder="Buscar ${micro?'microorganismo':'antibiótico'}…" value="${H(state.browserQuery)}"></label><div class="library-count">${filtered.length} de ${all.length} entradas <button data-act="clear-library">Limpiar</button></div><div class="category-dropdown"><select id="library-filter" aria-label="Filtrar categoría"><option value="all">Todas las ${micro?'familias microbiológicas':'familias de ATB'}</option>${values.map(([id,label,n])=>`<option value="${H(id)}" ${filter===id?'selected':''}>${H(label)} (${n})</option>`).join('')}</select></div><div class="browser-results">${filtered.slice(0,80).map(x=>`<button data-act="select-${kind}:${x.id}" class="browser-entry ${x.id===chosen.id?'selected':''}" ${micro?groupStyle(x.groupId):''}><span ${micro?'class="dot"':''}></span><span><strong>${H(x.name)}</strong><small>${H(micro?G(x.groupId)?.name:x.subgroup||x.family)}</small></span>${ic('chevron',14)}</button>`).join('')||'<p class="empty-info">No hay coincidencias.</p>'}</div></aside><div class="library-profile">${micro?microProfile(chosen):drugProfile(chosen)}</div></div>`}
function microProfile(p){if(!p)return'';const g=G(p.groupId),rels=relsP(p.id),media=X.media?.[p.id];const tab=state.profileTab;const tabs=[['identidad','Identidad'],['enfermedad','Enfermedades'],['cobertura','Relaciones ATB'],['fuentes','Bibliografía']];return `<div class="profile-banner" ${groupStyle(p.groupId)}><div><span class="profile-pretitle"><i></i>${H(g?.name||'Grupo')} / ${H(p.domain||'')}</span><h2>${H(p.name)}</h2><p>${H(p.identity||'La identidad y el contexto clínico deben interpretarse de forma conjunta.')}</p><div class="tag-row">${pill(p.morphology||'Morfología pendiente')}${pill(p.domain||'Dominio')}${p.aliases?.slice(0,2).map(pill).join('')||''}</div></div>${media?`<figure class="micro-photo"><img src="${H(media.src)}" loading="lazy" alt="Microfotografía de ${H(p.name)}"><figcaption>${H(media.credit)} · <a href="${H(media.creditUrl)}" target="_blank" rel="noopener noreferrer">CDC PHIL</a></figcaption></figure>`:`<div class="morphology-mark">${ic('micro',56)}<span>MORFOLOGÍA<br>REFERENCIA</span></div>`}</div><div class="profile-stats"><div><small>GRUPO</small><b>${H(g?.name||'—')}</b></div><div><small>MORFOLOGÍA</small><b>${H(p.morphology||'—')}</b></div><div><small>RELACIONES EN BASE</small><b>${rels.length} / ${D.antibiotics.length}</b></div></div><div class="profile-tabs">${tabs.map(([k,t])=>`<button class="${tab===k?'on':''}" data-act="profile-tab:${k}">${t}</button>`).join('')}</div><div class="profile-body">${tab==='identidad'?`${microRelationsDossier(p)}<div class="reading-grid"><section><h3>Reconocimiento y significado clínico</h3><p>${H(p.identity||'Datos por completar')}</p><h4>¿En qué contexto pensarlo?</h4><p>${H(p.clinical||'El foco y el huésped determinan probabilidad pretest.')}</p><div class="teacher-note">${ic('note',20)}<div><b>Perla diagnóstica</b><p>${H(p.pearl||'No interpretar especie sin contexto.')}</p></div></div></section><aside class="profile-side"><b>La secuencia de interpretación</b><ol><li>Gram, morfología y agrupación.</li><li>Reservorio y síndrome probable.</li><li>Identificación microbiológica.</li><li>Fenotipo y susceptibilidad.</li></ol>${button('Ver en el mapa','micro-map:'+p.id,'primary','map')}</aside></div>`:tab==='enfermedad'?`<h3>Escenarios y enfermedades</h3><p>${H(p.clinical||'No hay una asociación clínica detallada.')}</p><div class="link-tiles">${(p.syndromeIds||[]).map(id=>S(id)?`<button data-act="open-syndrome:${id}">${ic('clinic',18)}<span>${H(S(id).name)}<small>${H(S(id).site)}</small></span>${ic('next',14)}</button>`:'').join('')||'<p>No hay vínculos individuales definidos en este archivo.</p>'}</div>`:tab==='cobertura'?`<div class="notice educational">${ic('info',18)} Estas son relaciones <b>registradas</b>, no un antibiograma. Las otras ${D.antibiotics.length-rels.length} combinaciones permanecen sin evaluar.</div><h3>ATB documentados en el corpus</h3>${relationList(rels,true)}${button('Comparar con este micro','compare-micro:'+p.id,'primary','compare')}`:`<h3>Fuentes asociadas a la ficha</h3>${linkRefs(p.referenceKeys)}<p class="muted">Identidad docente preliminar. Referencias del catálogo y fuentes enlazadas, sin atribuir recomendaciones clínicas al libro de manera automática.</p>`}</div>`}
function relationList(list,byMicro=false){const order={active:0,conditional:1,none:2,unknown:3};return list.length?`<div class="relation-list">${[...list].sort((a,b)=>order[rstatus(a)]-order[rstatus(b)]).map(r=>{const e=byMicro?A(r.antibiotic):P(r.pathogen);return `<button data-act="${byMicro?'open-drug:'+e.id:'open-micro:'+e.id}">${statusBadge(rstatus(r))}<span><b>${H(e?.name)}</b><small>${H(r.note||'Relación pendiente de revisión individual')}</small></span>${ic('chevron',15)}</button>`}).join('')}</div>`:'<p class="empty-info">No existen relaciones individuales cargadas para esta ficha. No significa ausencia de cobertura.</p>'}
function drugProfile(a){const tab=state.drugTab,rels=relsA(a.id),family=D.antibiotics.filter(x=>x.family===a.family);const tabs=[['resumen','Perfil'],['mecanismo','Farmacología'],['cobertura','Microorganismos'],['comparar','Comparar y fuentes']];return `<div class="profile-banner drug-banner"><div><span class="profile-pretitle">ANTIBIÓTICO / ${H(a.family)} / ${H(a.subgroup||'Subgrupo')}</span><h2>${H(a.name)}</h2><p>${H(a.pearl||'Analiza la clase y el contexto clínico.')}</p><div class="tag-row">${pill(a.mechanism?.split(':')[0]||'Mecanismo a revisar')}${a.newer?pill('Agente nuevo/especializado'):''}${pill(a.review?.includes('pendiente')?'Revisión pendiente':'Ficha bibliográfica')}</div></div><div class="drug-identity">${ic('drugs',52)}<span>Rx / ${H(a.family)}</span></div></div><div class="profile-stats"><div><small>FAMILIA</small><b>${H(a.family)}</b></div><div><small>SUBGRUPO</small><b>${H(a.subgroup||'—')}</b></div><div><small>RELACIONES REGISTRADAS</small><b>${rels.length} / ${D.pathogens.length}</b></div></div><div class="profile-tabs">${tabs.map(([k,t])=>`<button class="${tab===k?'on':''}" data-act="drug-tab:${k}">${t}</button>`).join('')}</div><div class="profile-body">${tab==='resumen'?`${drugSpectrumDossier(a)}<div class="reading-grid"><section><h3>Para qué sirve conceptualmente</h3><p>${H(a.context||'Consultar las indicaciones autorizadas y el foco clínico.')}</p><h4>Lo que conviene reconocer</h4><p>${H(a.pearl||'No extrapolar desde el nombre de la familia.')}</p><div class="teacher-note">${ic('alert',19)}<div><b>Limitación importante</b><p>${H(a.limitations||'Individualizar según especie, foco y susceptibilidad.')}</p></div></div></section><aside class="profile-side"><b>Miembros de la familia</b><div class="sibling-list">${family.slice(0,14).map(x=>`<button data-act="open-drug:${x.id}" class="${x.id===a.id?'current':''}">${H(x.name)} ${ic('chevron',12)}</button>`).join('')}</div></aside></div>`:tab==='mecanismo'?`<div class="reading-grid"><section><h3>¿Cuál es su diana?</h3><p>${H(a.mechanism||'Mecanismo pendiente de completar')}</p><h4>Conectar mecanismo y espectro</h4><p>El espectro no depende solo de la diana; la entrada, estabilidad frente a enzimas, distribución y exposición PK/PD modifican la actividad.</p></section><aside class="profile-side"><b>Ficha de estudio</b><ol><li>Familia / subgrupo.</li><li>Diana y mecanismo de acción.</li><li>Patógenos relevantes.</li><li>Resistencia típica y limitaciones.</li><li>Penetración y seguridad.</li></ol></aside></div>`:tab==='cobertura'?`<div class="notice educational">${ic('info',18)} Solo <b>${rels.length}</b> de ${D.pathogens.length} pares tienen registro en este corpus. «Sin evaluar» no significa resistencia.</div><h3>Relaciones individuales disponibles</h3>${relationList(rels,false)}`:`<div class="reading-grid"><section><h3>Comparar con otros antibióticos</h3><p>Selecciona este agente como punto de partida. El comparador no inventa valores para los microorganismos sin relación registrada.</p>${button('Enviar al comparador','add-compare:'+a.id,'primary','compare')}</section><aside class="profile-side"><b>Referencias bibliográficas</b>${linkRefs(a.referenceKeys)}</aside></div>`}</div>`}
function legacy_libraryPage(micro){return `${pageHead(micro?'02':'03','BIBLIOTHECA',micro?'Los microorganismos, <em>por dentro.</em>':'Los antibióticos, <em>con criterio.</em>',micro?'Del Gram al síndrome, del fenotipo a las relaciones registradas. Explora 79 fichas organizadas, sin muros de tarjetas.':'111 agentes en 26 familias. Separa el mecanismo del espectro y aprende por qué cada subgrupo tiene límites propios.',button(micro?'Ir a antibióticos':'Ir a microorganismos',micro?'nav:atb':'nav:micro','secondary',micro?'drugs':'micro'))}${catalog(micro?'micro':'atb')}`}
function siteTabs(){const sites=[...new Set(D.syndromes.map(s=>s.site))];return `<div class="site-tabs"><button data-act="site:all" class="${state.site==='all'||!state.site?'on':''}">Todos</button>${sites.map(site=>`<button data-act="site:${H(site)}" class="${state.site===site?'on':''}">${H(site)}</button>`).join('')}</div>`}
function legacy_clinicalPage(){const s=S(state.syndrome),tab=state.clinicalTab,filtered=D.syndromes.filter(x=>!state.site||state.site==='all'||x.site===state.site);return `${pageHead('04','ROUTES / CLÍNICA','Del síndrome a <em>la hipótesis.</em>','Cuatro decisiones antes de prescribir: foco, gravedad, agentes probables y pruebas o guías que modifican el plan.')}${siteTabs()}<div class="clinical-layout"><aside class="clinical-browser">${filtered.map(x=>`<button class="${s.id===x.id?'current':''}" data-act="syndrome:${x.id}"><span>${H(x.site)}</span><b>${H(x.name)}</b>${ic('chevron',15)}</button>`).join('')}</aside><article class="clinical-article">${tag('SÍNDROME ACTIVO / '+s.site)}<h2>${H(s.name)}</h2><p>${H(s.summary)}</p><div class="clinical-track"><div><b>01</b><strong>Reconocer</strong><small>Foco e infección</small></div><div><b>02</b><strong>Estratificar</strong><small>Gravedad y huésped</small></div><div><b>03</b><strong>Priorizar</strong><small>Microorganismos probables</small></div><div><b>04</b><strong>Verificar</strong><small>Muestras, guía y evolución</small></div></div><div class="profile-tabs compact-tabs">${[['panorama','Panorama'],['pistas','Qué cambia'],['patogenos','Microorganismos'],['guias','Fuentes']].map(([k,t])=>`<button class="${tab===k?'on':''}" data-act="clinical-tab:${k}">${t}</button>`).join('')}</div><div class="profile-body">${tab==='panorama'?`<h3>Qué necesito definir primero</h3><div class="question-list">${(s.clues||[]).slice(0,7).map((x,i)=>`<div><span>${('0'+(i+1)).slice(-2)}</span><p>${H(x)}</p></div>`).join('')}</div><div class="teacher-note">${ic('note',19)}<div><b>Enfoque para el estudio</b><p>Construye primero el diagnóstico sindrómico. La elección antibiótica debe ajustarse a la gravedad, microbiología disponible y recomendaciones vigentes.</p></div></div>`:tab==='pistas'?`<h3>Elementos que cambian el abordaje</h3><div class="question-list">${(s.clues||[]).map((x,i)=>`<div><span>${('0'+(i+1)).slice(-2)}</span><p>${H(x)}</p></div>`).join('')}</div><div class="notice educational">${ic('info',18)} En ITU complicada la IDSA 2025 propone considerar gravedad, resistencia previa, factores del paciente y antibiograma local cuando sea aplicable.</div>`:tab==='patogenos'?`<h3>Agentes vinculados en el catálogo</h3><div class="link-grid">${(s.pathogenIds||[]).map(id=>P(id)?`<button ${groupStyle(P(id).groupId)} data-act="open-micro:${id}"><i></i><span><b>${H(P(id).name)}</b><small>${H(P(id).morphology||'')}</small></span>${ic('chevron',15)}</button>`:'').join('')||'<p>No hay patógenos vinculados en esta ficha.</p>'}</div>`:`<h3>Guías y recursos del síndrome</h3>${linkRefs(s.referenceKeys)}<p>Comprueba fecha, ámbito y población antes de trasladar recomendaciones al paciente.</p>`}</div></article></div>`}
function legacy_comparePage(){const micro=P(state.compareMicro)||D.pathogens[0],drugs=state.compare.map(A).filter(Boolean);return `${pageHead('05','COMPARISON ROOM','Comparar sin <em>adivinar.</em>','Hasta cuatro agentes frente a una misma especie. Un «sin datos» sigue siendo un dato ausente, nunca una resistencia inferida.') }<div class="compare-controls"><label>Microorganismo<select id="compare-micro">${D.groups.map(g=>`<optgroup label="${H(g.name)}">${members(g.id).map(p=>`<option ${micro.id===p.id?'selected':''} value="${H(p.id)}">${H(p.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><label>Añadir antibiótico<select id="compare-add"><option value="">Selecciona un ATB…</option>${D.antibiotics.map(a=>`<option value="${a.id}">${H(a.name)}</option>`).join('')}</select></label>${button('Reiniciar','compare-reset','ghost','reset')}</div><div class="compare-reading"><div>${tag('MICROORGANISMO SELECCIONADO')}<h2>${H(micro.name)}</h2><p>${H(micro.identity)}</p></div><div class="compare-meter"><b>${drugs.length}</b><span>de 4 espacios en uso</span></div></div><div class="compare-columns">${drugs.map(a=>{const r=relation(a.id,micro.id),v=rstatus(r);return `<article class="compare-col"><div class="compare-col-head"><span>${H(a.family)}</span><button data-act="remove-compare:${a.id}">${ic('close',15)}</button></div><h3>${H(a.name)}</h3>${statusBadge(v)}<div class="comparison-tile"><small>MECANISMO</small><p>${H(a.mechanism||'Por revisar')}</p></div><div class="comparison-tile"><small>CONTEXTO</small><p>${H(a.context||'Por completar')}</p></div><div class="comparison-tile"><small>RELACIÓN INDIVIDUAL</small><p>${H(r?.note||'No existe un registro para esta combinación.')}</p></div><div class="comparison-tile"><small>LIMITACIONES</small><p>${H(a.limitations||'Según especie, foco y susceptibilidad.')}</p></div>${button('Ver ficha','open-drug:'+a.id,'secondary','drugs')}</article>`}).join('')}${drugs.length<4?`<div class="compare-empty">${ic('compare',32)}<b>Espacio disponible</b><p>Añade otro antibiótico desde el selector. Las columnas crecen hasta cuatro sin perder su correspondencia con el microorganismo.</p></div>`:''}</div><div class="notice caution">${ic('alert',18)} El comparador muestra relaciones piloto no revisadas individualmente. No lo utilices como selector terapéutico automático.</div>`}
function lessonList(){const groups=[...new Set(F.chapters.map(c=>c.stage))];return `<div class="lesson-navigation">${groups.map(stage=>`<section><header><b>${H(stage)}</b><span>${F.chapters.filter(c=>c.stage===stage).length} temas</span></header>${F.chapters.filter(c=>c.stage===stage).map(c=>`<button data-act="lesson:${c.id}" class="${state.lesson===c.id?'current':''}"><span>${c.num}</span><strong>${H(c.title)}</strong>${state.completed.includes(c.id)?ic('star',15):''}</button>`).join('')}</section>`).join('')}</div>`}
function legacy_learningPage(){const c=F.chapters.find(x=>x.id===state.lesson)||F.chapters[0],idx=F.chapters.indexOf(c);return `${pageHead('06','MEDICAL ACADEMY','Antes de resistencias, <em>comprensión.</em>','24 capítulos progresivos: microbiología fundamental → espectro y mecanismo → diagnóstico y clínica → resistencia y aplicación. Cada tema incluye ejemplo y autoevaluación.',`<div class="progress-summary">${ic('learn',19)} <b>${state.completed.length} / 24</b> completados</div>`)}<div class="learning-layout"><aside>${lessonList()}</aside><article class="lesson-reader"><div class="reader-overline"><span>CAPÍTULO ${c.num} / ${H(c.stage)}</span><span>TIEMPO DE LECTURA · 4–6 MIN</span></div><h2>${H(c.title)}</h2><p class="lesson-lead">${H(c.lead)}</p><div class="lesson-illustration"><div>${ic('book',32)}<span>PRINCIPIO CENTRAL</span></div><p>${H(c.detail)}</p></div><h3>Tres ideas que deben permanecer</h3><div class="learn-takeaways">${c.keys.map((x,i)=>`<div><span>${('0'+(i+1)).slice(-2)}</span><p>${H(x)}</p></div>`).join('')}</div><div class="example-note"><b>Ejemplo aplicado</b><p>${H(c.case)}</p></div><div class="study-check"><div><span>AUTOEVALUACIÓN</span><h3>${H(c.question)}</h3></div>${state.lessonAnswered?`<div class="answer-panel">${ic('star',20)}<p>${H(c.answer)}</p></div>`:button('Mostrar explicación','lesson-answer','primary','note')}<div class="lesson-pager">${button('Anterior','lesson-index:'+Math.max(0,idx-1),'secondary','chevron')}${button(state.completed.includes(c.id)?'Revisado ✓':'Marcar aprendido','lesson-complete','secondary','star')}${button('Siguiente','lesson-index:'+Math.min(F.chapters.length-1,idx+1),'primary','next')}</div></div><div class="study-sources"><small>Fuentes de apoyo y ampliación</small>${linkRefs(c.refs)}</div></article></div>`}
function legacy_labPage(){const s=S(state.labSyndrome),p=P(state.labMicro),a=A(state.labDrug),r=s&&p&&a?relation(a.id,p.id):null;return `${pageHead('07','HANDS-ON / LABORATORY','Aprender <em>haciendo preguntas.</em>','Un recorrido interactivo que enseña primero el síndrome, luego los microorganismos y finalmente cómo interpretar un antibiótico. Sin tarjetas vacías ni comparaciones arbitrarias.') }<div class="lab-path"><div class="lab-stage-tabs"><button data-act="lab-step:0" class="${state.labStep===0?'on':''}"><span>01</span> SÍNDROME</button><button data-act="lab-step:1" class="${state.labStep===1?'on':''}"><span>02</span> MICROORGANISMO</button><button data-act="lab-step:2" class="${state.labStep===2?'on':''}"><span>03</span> ANTIBIÓTICO</button><button data-act="lab-step:3" class="${state.labStep===3?'on':''}"><span>04</span> INTERPRETACIÓN</button></div><div class="lab-lesson"><div class="lab-step-tag">ETAPA ${('0'+(state.labStep+1)).slice(-2)} DE 04</div>${state.labStep===0?`<h2>¿Cuál es la situación clínica?</h2><p>El punto de partida no es el fármaco. Elige un síndrome para construir la hipótesis.</p><div class="lab-choices">${D.syndromes.slice(0,18).map(x=>`<button data-act="lab-syndrome:${x.id}" class="${x.id===state.labSyndrome?'chosen':''}"><b>${H(x.name)}</b><small>${H(x.site)}</small></button>`).join('')}</div>${s?`<div class="lab-reading"><b>Lo que ya sabes</b><p>${H(s.summary)}</p></div>`:''}`:state.labStep===1?`<h2>¿Qué microorganismos considerarías?</h2><p>Los candidatos proceden de los vínculos del síndrome. No son una lista exhaustiva ni sustituyen probabilidad clínica.</p><div class="lab-choices">${(s?.pathogenIds||[]).map(id=>P(id)?`<button data-act="lab-micro:${id}" class="${id===state.labMicro?'chosen':''}" ${groupStyle(P(id).groupId)}><i class="dot"></i><b>${H(P(id).name)}</b><small>${H(P(id).morphology)}</small></button>`:'').join('')}</div>${p?`<div class="lab-reading"><b>Cómo reconocerlo</b><p>${H(p.identity)}</p></div>`:''}`:state.labStep===2?`<h2>¿Qué antibiótico explorarías?</h2><p>Elige un fármaco para revisar su perfil y la disponibilidad de un cruce documentado; no intentamos recomendar tratamiento automáticamente.</p><div class="lab-combo"><label>Familia / agente<select id="lab-drug"><option value="">Elige un antibiótico…</option>${D.antibiotics.map(x=>`<option value="${x.id}" ${x.id===state.labDrug?'selected':''}>${H(x.name)} · ${H(x.family)}</option>`).join('')}</select></label></div>${a?`<div class="lab-reading"><b>Mecanismo y contexto</b><p><strong>${H(a.mechanism)}</strong></p><p>${H(a.context)}</p></div>`:''}`:`<h2>¿Qué podemos concluir realmente?</h2><p>El resultado depende de los datos disponibles. Debes distinguir <b>actividad teórica, relación registrada y recomendación clínica</b>.</p><div class="lab-result"><div><small>SÍNDROME</small><b>${H(s?.name||'—')}</b></div><div><small>MICRO</small><b>${H(p?.name||'—')}</b></div><div><small>ATB</small><b>${H(a?.name||'—')}</b></div><div><small>REGISTRO</small>${statusBadge(rstatus(r))}</div></div><div class="lab-reading"><b>${r?'Existe un registro preliminar':'No hay un cruce registrado'}</b><p>${H(r?.note||'Este vacío no permite inferir actividad ni resistencia. Consulta una fuente clínica y microbiológica válida antes de decidir.')}</p></div><div class="lab-reflection"><b>Preguntas para terminar</b><p>¿Qué especie y fenotipo están identificados? ¿Hay un antibiograma? ¿Penetra el fármaco en el sitio? ¿Requiere control de foco? ¿Qué dice la guía vigente?</p></div>`}<div class="lab-bottom">${button('Volver','lab-prev','secondary','chevron')}${button('Reiniciar','lab-reset','ghost','reset')}${button(state.labStep===3?'Explorar el mapa':'Siguiente paso',state.labStep===3?'lab-to-map':'lab-next','primary','next')}</div></div></div>`}
function legacy_sourcesPage(){const guides=Object.entries(D.guides);return `${pageHead('08','REFERENCE DESK','Fuentes y <em>trazabilidad.</em>','Consulta documentos concretos; la existencia de una referencia en la biblioteca no significa que todos los cruces estén verificados.') }<div class="sources-grid">${guides.map(([id,g])=>`<article class="guide-card"><span>${H(g.category||'Referencia')} · ${H(g.year||'')}</span><h3>${H(g.title)}</h3><p>${H(g.topic||'')}</p><div>${H(g.takeaway||'')}</div>${g.url?`<a href="${H(g.url)}" target="_blank" rel="noopener noreferrer">Abrir fuente ${ic('external',15)}</a>`:'<small>Fuente bibliográfica aportada por el usuario · consultar material original</small>'}</article>`).join('')}</div>`}
function modal(){if(!state.modal)return '';let content='';if(state.modal==='palette')content=`<h2>Editor de colores</h2><p>Cada grupo microbiológico tiene un tono propio; el color identifica taxonomía, <strong>no</strong> susceptibilidad.</p><div class="palette-presets">${Object.keys(PRESETS).map(k=>`<button data-act="preset:${k}">${k}<span>${PRESETS[k].slice(0,6).map(x=>`<i style="background:${x}"></i>`).join('')}</span></button>`).join('')}</div><div class="palette-list">${D.groups.map((g,i)=>`<label><span>${H(g.name)}</span><input type="color" data-change="color:${i}" value="${H(grpcolor(g.id))}"></label>`).join('')}</div>${button('Restablecer colores','palette-reset','secondary','reset')}`;
if(state.modal==='legend')content=`<h2>Cómo leer el mapa</h2><p>El encabezado de color representa <b>un grupo microbiológico</b>. Los segmentos indican la existencia y el tipo de una relación individual.</p><div class="legend-extended">${Object.keys(ST).map(k=>`<div>${statusBadge(k)}<p>${H(ST[k].help)}</p></div>`).join('')}</div><div class="notice educational">Una banda con «0/7» indica que ninguna de las siete relaciones del grupo fue evaluada en este corpus, NO que el ATB falle contra siete microorganismos.</div>`;
if(state.modal==='search')content=`<h2>Buscar en el atlas</h2><label class="search-control">${ic('search',17)}<input autofocus id="global-search" value="${H(state.globalSearch||'')}" placeholder="Empieza a escribir cefepima, MRSA, neumonía…"></label><div class="global-results">${searchResults()}</div>`;
if(state.modal==='saved')content=`<h2>Mis mapas guardados</h2><p>Estas vistas se conservan solo en este navegador.</p>${state.savedViews.map((v,i)=>`<button data-act="load-view:${i}"><b>${H(v.name)}</b><small>${H(v.family)} · ${H(v.group)}</small>${ic('chevron',15)}</button>`).join('')||'<p>Todavía no has guardado mapas.</p>'}`;
return `<div class="modal-backdrop" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true"><div class="modal-top"><span>ATB / ATLAS · HERRAMIENTAS</span><button data-act="close-modal">${ic('close',17)}</button></div>${content}</div></div>`}
function searchResults(){const t=(state.globalSearch||'').toLowerCase().trim();if(!t)return `<p class="muted">Busca dentro de ${D.antibiotics.length} antibióticos, ${D.pathogens.length} microorganismos y ${D.syndromes.length} síndromes.</p>`;const arr=[...D.antibiotics.map(x=>({name:x.name,kind:'ATB',act:'open-drug:'+x.id})),...D.pathogens.map(x=>({name:x.name,kind:'MICRO',act:'open-micro:'+x.id})),...D.syndromes.map(x=>({name:x.name,kind:'CLÍNICA',act:'open-syndrome:'+x.id}))];return arr.filter(x=>x.name.toLowerCase().includes(t)).slice(0,18).map(x=>`<button data-act="${x.act}"><small>${x.kind}</small><b>${H(x.name)}</b>${ic('chevron',14)}</button>`).join('')||'<p>Sin resultados.</p>'}
function mainPage(){switch(state.route){case 'mapa':return mapPage();case 'micro':return libraryPage(true);case 'atb':return libraryPage(false);case 'clinica':return clinicalPage();case 'comparar':return comparePage();case 'aprender':return learningPage();case 'laboratorio':return labPage();case 'fuentes':return sourcesPage();default:return mapPage();}}
function render(){if(!D)return;applyColors();$('#app').innerHTML=frame(mainPage());}
function legacy_act(arg){const [op,...parts]=arg.split(':'),val=parts.join(':');switch(op){
case 'nav':return goto(val);
case 'menu':$('#site-nav')?.classList.toggle('mobile-open');return;
case 'palette':state.modal='palette';break;
case 'legend':state.modal='legend';break;
case 'search-global':state.modal='search';break;
case 'close-modal':state.modal='';break;
case 'preset':state.palette=[...PRESETS[val]];persist();break;
case 'palette-reset':state.palette=[...GROUP_PALETTE];persist();break;
case 'group':state.group=val;state.page=0;state.inspect=null;break;
case 'drug-territory':{const [drug,group]=parts;state.group=group;state.family='all';state.search=A(drug)?.name||'';state.onlyKnown=false;state.page=0;state.inspect={drug,group};return goto('mapa');}
case 'quick':{const p=P(val);if(p){state.group=p.groupId;state.page=0;const row=mapDrugs().find(a=>relation(a.id,p.id))||mapDrugs()[0]||D.antibiotics[0];state.inspect={drug:row.id,group:p.groupId,pathogen:p.id}}break;}
case 'filter-group':state.group=val;state.inspect=null;return goto('mapa');
case 'scope':state.scope=val;break;
case 'toggle-filters':state.showFilters=!state.showFilters;break;
case 'reset-map':Object.assign(state,{group:'all',family:'all',search:'',onlyKnown:true,sort:'evidence',favoritesOnly:false,page:0,inspect:null,showFilters:false});break;
case 'inspect':{const [drug,group]=parts;state.inspect={drug,group};break;}
case 'species':state.inspect={...state.inspect,pathogen:val};break;
case 'relation':{const [drug,pathogen]=parts;state.inspect={drug,group:P(pathogen)?.groupId||D.groups[0].id,pathogen};break;}
case 'close-inspector':state.inspect=null;break;
case 'status':state.modal='legend';break;
case 'prev-page':state.page=Math.max(0,state.page-1);break;
case 'next-page':state.page++;break;
case 'open-drug':state.drug=val;state.browserQuery='';state.drugTab='resumen';return goto('atb');
case 'open-micro':state.micro=val;state.browserQuery='';state.profileTab='identidad';return goto('micro');
case 'open-syndrome':state.syndrome=val;state.clinicalTab='panorama';return goto('clinica');
case 'select-micro':state.micro=val;state.profileTab='identidad';break;
case 'select-atb':state.drug=val;state.drugTab='resumen';break;
case 'profile-tab':state.profileTab=val;break;
case 'drug-tab':state.drugTab=val;break;
case 'clinical-tab':state.clinicalTab=val;break;
case 'clear-library':state.browserQuery='';state.microGroup='all';state.drugFamily='all';break;
case 'micro-map':state.group=P(val)?.groupId||'all';state.inspect=null;return goto('mapa');
case 'syndrome':state.syndrome=val;state.clinicalTab='panorama';break;
case 'site':state.site=val;state.syndrome=(D.syndromes.find(s=>val==='all'||s.site===val)||D.syndromes[0]).id;break;
case 'compare-micro':state.compareMicro=val;return goto('comparar');
case 'add-compare':if(!state.compare.includes(val)){if(state.compare.length>=4)state.compare.shift();state.compare.push(val)}return goto('comparar');
case 'remove-compare':state.compare=state.compare.filter(id=>id!==val);break;
case 'compare-reset':state.compare=[];break;
case 'lesson':state.lesson=val;state.lessonAnswered=false;break;
case 'lesson-answer':state.lessonAnswered=true;break;
case 'lesson-complete':if(!state.completed.includes(state.lesson))state.completed.push(state.lesson);else state.completed=state.completed.filter(x=>x!==state.lesson);persist();break;
case 'lesson-index':state.lesson=F.chapters[Number(val)]?.id||state.lesson;state.lessonAnswered=false;break;
case 'lab-step':state.labStep=Number(val);break;
case 'lab-syndrome':state.labSyndrome=val;state.labMicro='';state.labDrug='';break;
case 'lab-micro':state.labMicro=val;state.labDrug='';break;
case 'lab-next':if(state.labStep===0&&!state.labSyndrome)break;if(state.labStep===1&&!state.labMicro)break;if(state.labStep===2&&!state.labDrug)break;state.labStep=Math.min(3,state.labStep+1);break;
case 'lab-prev':state.labStep=Math.max(0,state.labStep-1);break;
case 'lab-reset':state.labStep=0;state.labMicro='';state.labDrug='';state.labSyndrome='';break;
case 'lab-to-map':state.group=P(state.labMicro)?.groupId||'all';return goto('mapa');
case 'show-views':state.modal='saved';break;
case 'save-view':state.savedViews.unshift({name:new Date().toLocaleString('es-MX'),group:state.group,family:state.family,search:state.search,onlyKnown:state.onlyKnown});state.savedViews=state.savedViews.slice(0,10);state.modal='saved';persist();break;
case 'load-view':Object.assign(state,state.savedViews[Number(val)]||{});state.modal='';return goto('mapa');
case 'favorites':if(state.favorites.includes(val))state.favorites=state.favorites.filter(x=>x!==val);else state.favorites.push(val);persist();break;
}
render();if(op==='inspect'||op==='species')setTimeout(()=>{const el=$('#inspector');if(el&&innerWidth<1100)el.scrollIntoView({behavior:'smooth',block:'start'})},30);
if(op==='search-global')setTimeout(()=>$('#global-search')?.focus(),60);
}
document.addEventListener('click',e=>{const node=e.target.closest('[data-act]');if(!node)return;if(node.classList.contains('modal-backdrop')&&e.target!==node)return;e.preventDefault();act(node.getAttribute('data-act'));});
document.addEventListener('change',e=>{const n=e.target;if(n.id==='map-family'){state.family=n.value;state.page=0;}else if(n.id==='map-known'){state.onlyKnown=n.checked;state.page=0;}else if(n.id==='map-sort'){state.sort=n.value;state.page=0;}else if(n.id==='map-fav'){state.favoritesOnly=n.checked;state.page=0;}else if(n.id==='library-filter'){if(state.route==='micro')state.microGroup=n.value;else state.drugFamily=n.value;state.browserQuery='';const list=state.route==='micro'?D.pathogens:D.antibiotics;const field=state.route==='micro'?'groupId':'family';const selected=list.find(x=>n.value==='all'||x[field]===n.value);if(selected){if(state.route==='micro')state.micro=selected.id;else state.drug=selected.id}}else if(n.id==='compare-micro')state.compareMicro=n.value;else if(n.id==='compare-add'){if(n.value){act('add-compare:'+n.value);return}}else if(n.id==='lab-drug')state.labDrug=n.value;else if(n.dataset.change?.startsWith('color:')){const i=Number(n.dataset.change.split(':')[1]);state.palette??=[...GROUP_PALETTE];state.palette[i]=n.value;persist();}else return;render()});
let searchTyping=false;
document.addEventListener('input',e=>{const n=e.target;if(n.id==='map-search'){state.search=n.value;state.page=0;searchTyping=true;render();const z=$('#map-search');z?.focus();z?.setSelectionRange(z.value.length,z.value.length);}else if(n.id==='library-search'){state.browserQuery=n.value;searchTyping=true;render();const z=$('#library-search');z?.focus();z?.setSelectionRange(z.value.length,z.value.length);}else if(n.id==='global-search'){state.globalSearch=n.value;const x=$('.global-results');if(x)x.innerHTML=searchResults();}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();act('search-global')}if(e.key==='Escape'&&state.modal){state.modal='';render()}});
let scriptsReady=document.readyState==='complete';document.addEventListener('DOMContentLoaded',()=>{scriptsReady=true},{once:true});
(async function init(){try{const [a,b,c]=await Promise.all(['data/atlas.json','data/insights.json','data/fundamentals.json'].map(p=>fetch(p,{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error(p+' HTTP '+r.status);return r.json()})));
 if(!scriptsReady)await new Promise(r=>document.addEventListener('DOMContentLoaded',r,{once:true}));/* deferred layers V18–V26 wrap render(): do not paint before they have all run */
 D=a;X=b;F=c;D.relations.forEach(r=>{byPair.set(r.antibiotic+'|'+r.pathogen,r);if(!byDrug.has(r.antibiotic))byDrug.set(r.antibiotic,[]);if(!byPath.has(r.pathogen))byPath.set(r.pathogen,[]);byDrug.get(r.antibiotic).push(r);byPath.get(r.pathogen).push(r)});
 Object.assign(state,{drug:D.antibiotics.find(a=>relsA(a.id).length)?.id||D.antibiotics[0].id,micro:D.pathogens[0].id,syndrome:D.syndromes[0].id,compare:['cefepima','ceftriaxona','piperacilina-tazobactam','meropenem'].filter(id=>A(id)),compareMicro:'p-aeruginosa'});
 if(!state.compare.length)state.compare=D.antibiotics.filter(a=>relsA(a.id).length).slice(0,3).map(x=>x.id);
 if(!P(state.compareMicro))state.compareMicro=D.pathogens[0].id;
 const h=location.hash.replace(/^#\//,'').split('?')[0];if(NAV.some(x=>x[0]===h))state.route=h;
 escapeHandler();render();
 }catch(e){console.error(e);$('#app').innerHTML=`<div class="load-error"><h1>No se pudo abrir ATB Atlas</h1><p>${H(e.message)}</p><button onclick="location.reload()">Reintentar</button></div>`;}})();